package mvhpackbench;
import com.google.gson.*;import com.mojang.blaze3d.platform.GlStateManager;import com.mojang.blaze3d.systems.RenderSystem;import com.mojang.blaze3d.vertex.*;
import net.minecraft.client.Minecraft;import net.vulkanmod.gl.*;import net.vulkanmod.vulkan.*;import net.vulkanmod.vulkan.framebuffer.*;import net.vulkanmod.vulkan.texture.*;import net.vulkanmod.vulkan.shader.PipelineState;
import org.lwjgl.system.MemoryUtil;import java.nio.*;import java.nio.file.*;import java.security.*;import java.util.*;import static org.lwjgl.vulkan.VK10.*;

/** Real fixed-format logic pixels and D32 depth ordering; baseline defects remain explicit. */
final class NativeRasterStateSmoke {
    private static final int[] SOURCE={0x5A,0xC3,0x0F,0xCC},DEST={0xA5,0x3C,0xF0,0x55};
    private static int logic(int operation,int source,int destination){return(switch(operation){case 0->0;case 1->source&destination;case 2->source&~destination;case 3->source;case 4->~source&destination;case 5->destination;case 6->source^destination;case 7->source|destination;case 8->~(source|destination);case 9->~(source^destination);case 10->~destination;case 11->source|~destination;case 12->~source;case 13->~source|destination;case 14->~(source&destination);case 15->255;default->throw new AssertionError();})&255;}
    private static GlStateManager.LogicOp operation(int value){return Arrays.stream(GlStateManager.LogicOp.values()).filter(op->op.value==value).findFirst().orElseThrow();}
    private static void quad(float leftZ,float rightZ){var b=Tesselator.getInstance().getBuilder();b.begin(VertexFormat.Mode.QUADS,DefaultVertexFormat.POSITION);b.vertex(-1,-1,leftZ).endVertex();b.vertex(1,-1,rightZ).endVertex();b.vertex(1,1,rightZ).endVertex();b.vertex(-1,1,leftZ).endVertex();BufferUploader.drawWithShader(b.end());}
    private static int program(){int v=GlProgram.createShader(0x8B31),f=GlProgram.createShader(0x8B30),p=GlProgram.createProgram();GlProgram.shaderSource(v,"attribute vec3 Position;void main(){gl_Position=vec4(Position,1);}");GlProgram.shaderSource(f,"uniform vec4 color;void main(){gl_FragColor=color;}");GlProgram.compileShader(v);GlProgram.compileShader(f);GlProgram.attachShader(p,v);GlProgram.attachShader(p,f);GlProgram.bindAttribLocation(p,0,"Position");GlProgram.linkProgram(p);if(GlProgram.getProgrami(p,0x8B82)!=1)throw new IllegalStateException("Native state program failed");GlProgram.deleteShader(v);GlProgram.deleteShader(f);return p;}
    private static JsonObject pixels(VulkanImage image,String name,int[] expected)throws Exception{ByteBuffer pixels=MemoryUtil.memAlloc(256);try{ImageUtil.downloadTexture(image,MemoryUtil.memAddress(pixels));int mismatch=0,max=0;for(int i=0;i<64;i++){boolean bad=false;for(int c=0;c<4;c++){int difference=Math.abs((pixels.get(i*4+c)&255)-expected[c]);max=Math.max(max,difference);bad|=difference>1;}if(bad)mismatch++;}byte[] raw=new byte[256];pixels.get(0,raw);Path folder=Minecraft.getInstance().gameDirectory.toPath().resolve("mvh-raster-state-gpu-readback");Files.createDirectories(folder);Files.write(folder.resolve(name+".rgba"),raw);var result=new JsonObject();result.addProperty("case",name);result.addProperty("matched",mismatch==0);result.addProperty("compared_pixels",64);result.addProperty("mismatched_pixels",mismatch);result.addProperty("max_channel_difference",max);result.addProperty("channel_tolerance",1);result.addProperty("actual_rgba_sha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(raw)));return result;}finally{MemoryUtil.memFree(pixels);}}
    private static void start(Renderer renderer,RenderPass pass,Framebuffer fb,int shader,boolean logic,float depth,int[] background){renderer.beginRendering(pass,fb);Renderer.setOpenGlViewport(0,0,8,8);Renderer.setScissorEnabled(false);RenderSystem.disableCull();RenderSystem.disableBlend();VRenderSystem.disableStencilTest();VRenderSystem.colorMask(true,true,true,true);VRenderSystem.logicOp=logic;RenderSystem.clearColor(background[0]/255f,background[1]/255f,background[2]/255f,background[3]/255f);RenderSystem.clearDepth(depth);Renderer.clearAttachments(0x4000|0x100);GlProgram.useProgram(shader);GlProgram.uniform4f(GlProgram.getUniformLocation(shader,"color"),SOURCE[0]/255f,SOURCE[1]/255f,SOURCE[2]/255f,SOURCE[3]/255f);}
    static void run(JsonArray allCases)throws Exception{
        boolean baseline=Boolean.getBoolean("mvh.raster.baseline");JsonArray cases=new JsonArray();Renderer renderer=Renderer.getInstance();RenderPass previous=renderer.getBoundRenderPass();var state=new NativeStencilSmoke.State();int oldDepth=VRenderSystem.depthFun,oldLogic=VRenderSystem.logicOpFun;boolean oldLogicEnabled=VRenderSystem.logicOp,oldClip=Renderer.isScissorEnabled();int[] oldBox={Renderer.getScissorBox(0),Renderer.getScissorBox(1),Renderer.getScissorBox(2),Renderer.getScissorBox(3)};var oldBlend=PipelineState.blendInfo;
        var color=VulkanImage.builder(8,8).setFormat(VK_FORMAT_R8G8B8A8_UNORM).setUsage(VK_IMAGE_USAGE_COLOR_ATTACHMENT_BIT|VK_IMAGE_USAGE_TRANSFER_SRC_BIT|VK_IMAGE_USAGE_SAMPLED_BIT).createVulkanImage();var depth=VulkanImage.builder(8,8).setFormat(VK_FORMAT_D32_SFLOAT).setUsage(VK_IMAGE_USAGE_DEPTH_STENCIL_ATTACHMENT_BIT).createVulkanImage();var fb=Framebuffer.builder(color,depth).build();var passBuilder=RenderPass.builder(fb);passBuilder.getDepthAttachmentInfo().setOps(VK_ATTACHMENT_LOAD_OP_CLEAR,VK_ATTACHMENT_STORE_OP_STORE);var pass=passBuilder.build();int shader=program();
        try{VRenderSystem.disablePolygonOffset();RenderSystem.disableDepthTest();RenderSystem.depthMask(false);
            for(int i=0;i<16;i++){start(renderer,pass,fb,shader,true,1,DEST);VRenderSystem.logicOp(operation(0x1500+i));quad(0,0);int[] expected=new int[4];for(int c=0;c<4;c++)expected[c]=logic(i,SOURCE[c],DEST[c]);cases.add(pixels(color,"native-logic-operation-"+i,expected));}
            VRenderSystem.logicOp=false;RenderSystem.enableDepthTest();RenderSystem.depthMask(true);RenderSystem.depthFunc(513);int[] empty={0,0,0,0};
            start(renderer,pass,fb,shader,false,.5f,empty);VRenderSystem.polygonOffset(0,-4);VRenderSystem.enablePolygonOffset();quad(0,0);cases.add(pixels(color,"native-polygon-constant-units-negative",SOURCE));
            start(renderer,pass,fb,shader,false,.5f,empty);VRenderSystem.disablePolygonOffset();VRenderSystem.polygonOffset(-4,0);VRenderSystem.enablePolygonOffset();quad(0,0);cases.add(pixels(color,"native-polygon-factor-only-flat-no-shift",empty));
            start(renderer,pass,fb,shader,false,.8f,empty);VRenderSystem.disablePolygonOffset();VRenderSystem.polygonOffset(64,0);VRenderSystem.enablePolygonOffset();quad(.1f,.2f);cases.add(pixels(color,"native-polygon-slope-factor-positive",empty));
            start(renderer,pass,fb,shader,false,.5f,empty);VRenderSystem.disablePolygonOffset();VRenderSystem.polygonOffset(-4,-4);VRenderSystem.enablePolygonOffset();quad(0,0);cases.add(pixels(color,"native-polygon-live-update-initial-negative",SOURCE));
            start(renderer,pass,fb,shader,false,.5f,empty);VRenderSystem.polygonOffset(4,4);quad(0,0);cases.add(pixels(color,"native-polygon-live-update-positive-while-enabled",empty));
            start(renderer,pass,fb,shader,false,.5f,empty);VRenderSystem.disablePolygonOffset();quad(0,0);cases.add(pixels(color,"native-polygon-disable-removes-offset",empty));
            start(renderer,pass,fb,shader,false,.5f,empty);VRenderSystem.enablePolygonOffset();quad(0,0);cases.add(pixels(color,"native-polygon-reenable-retains-latest-values",empty));
        }finally{VRenderSystem.disablePolygonOffset();VRenderSystem.polygonOffset(0,0);GlProgram.useProgram(0);GlProgram.deleteProgram(shader);state.restore();VRenderSystem.logicOp=oldLogicEnabled;VRenderSystem.logicOpFun=oldLogic;PipelineState.blendInfo=oldBlend;RenderSystem.depthFunc(oldDepth);renderer.beginRendering(previous,previous.getFramebuffer());Renderer.setInvertedViewport(0,0,previous.getFramebuffer().getWidth(),previous.getFramebuffer().getHeight());Renderer.setScissor(oldBox[0],oldBox[1],oldBox[2],oldBox[3]);Renderer.setScissorEnabled(oldClip);renderer.invalidateRenderState();fb.cleanUp(false);pass.cleanUp();color.free();depth.free();}
        int logicFailures=0,biasFailures=0;for(var value:cases){var row=value.getAsJsonObject();if(!row.get("matched").getAsBoolean()){if(row.get("case").getAsString().startsWith("native-logic"))logicFailures++;else biasFailures++;}}
        var result=new JsonObject();result.addProperty("baseline_defect_reproduction",baseline);result.addProperty("candidate_accepted",!baseline&&logicFailures==0&&biasFailures==0);result.addProperty("logic_failures",logicFailures);result.addProperty("polygon_failures",biasFailures);result.addProperty("FPS_accepted",false);result.add("cases",cases);Files.writeString(Minecraft.getInstance().gameDirectory.toPath().resolve("mvh-raster-state-proof.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result));
        if(cases.size()!=23||baseline&&(logicFailures==0||biasFailures==0)||!baseline&&(logicFailures!=0||biasFailures!=0))throw new IllegalStateException("Native raster state GPU regression failed");if(!baseline)for(var row:cases)allCases.add(row);if(NativeGlErrors.consume()!=0)throw new IllegalStateException("Native raster state error queue");
    }
}
